import{_ as l,a0 as s,w as d,s as u,I as o,x as n,a1 as i,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse(`{"title":"Microsoft Linux 沒來，但微軟用更聰明的辦法贏了 | LCTT x X-CMD","titleTemplate":false,"description":"2020 年 TechRepublic Jack Wallen 提議微軟發 Microsoft Linux 桌面發行版。沒發生——但微軟用 WSL+Azure+VS Code+Copilot 這套'嵌入 Linux'路線贏麻了。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Microsoft Linux 沒來，但微軟用更聰明的辦法贏了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2020 年 TechRepublic Jack Wallen 提議微軟發 Microsoft Linux 桌面發行版。沒發生——但微軟用 WSL+Azure+VS Code+Copilot 這套'嵌入 Linux'路線贏麻了。"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20201012 Could Microsoft be en route to dumping Windows in favor of Linux.digest","title":"Microsoft Linux 沒來，但微軟用更聰明的辦法贏了","tag":"202010","desc":"2020 年 TechRepublic Jack Wallen 提議微軟發 Microsoft Linux 桌面發行版。沒發生——但微軟用 WSL+Azure+VS Code+Copilot 這套'嵌入 Linux'路線贏麻了。"},"relativePath":"202010/20201012 Could Microsoft be en route to dumping Windows in favor of Linux.digest.md","filePath":"[post].md"}`),f={name:"202010/20201012 Could Microsoft be en route to dumping Windows in favor of Linux.digest.md"},L={class:"table-wrap"};function p(x,t,c,g,m,W){const e=s("Link");return d(),u("div",null,[t[11]||(t[11]=o("h1",{id:"microsoft-linux-沒來-但微軟用更聰明的辦法贏了",tabindex:"-1"},[n("Microsoft Linux 沒來，但微軟用更聰明的辦法贏了 "),o("a",{class:"header-anchor",href:"#microsoft-linux-沒來-但微軟用更聰明的辦法贏了","aria-label":"Permalink to “Microsoft Linux 沒來，但微軟用更聰明的辦法贏了”"},"​")],-1)),o("blockquote",null,[o("p",null,[t[1]||(t[1]=n("老文新評 #062 · ",-1)),i(e,{href:"https://www.zdnet.com/article/linux-based-windows-makes-perfect-sense/",rel:"nofollow noopener"},{default:r(()=>[...t[0]||(t[0]=[n("ZDNet",-1)])]),_:1}),t[2]||(t[2]=n(" · 2020-10-12",-1))])]),t[12]||(t[12]=a('<p>2020 年 10 月，TechRepublic 的 Jack Wallen 寫了一篇相當激進的長文——<strong>&quot;微軟應該直接發佈自己的 Linux 桌面&quot;</strong>，不是 WSL、不是 Linux 子系統，而是 OEM 出廠預裝的完整 Linux 發行版，名字都幫你想好了：Microsoft Linux。</p><p>6 年後看這事，<strong>他猜對了一半</strong>——微軟確實在 WSL、Azure、VS Code、PowerShell、Edge 這些層面深度擁抱了 Linux。但 OEM 出廠預裝 Microsoft Linux？沒發生。微軟選了另一條路。</p><p>2020 年的微軟處於一個微妙的轉型期：Azure 已經是雲市場老二、Windows 桌面市場開始被 Chromebook 和 Mac 蠶食、WSL 已經迭代到第二代（帶真 Linux 內核）、VS Code 成為最流行的跨平台編輯器。那一年也是疫情爆發期，遠程辦公突然成為主流，Linux 桌面首次真正進入主流企業視野。Wallen 這篇文章正是在這個時間窗口提出「微軟應該 all-in Linux」——結合 Eric Raymond 當時那條「桌面戰爭終戰」的論點。</p><h2 id="文章講了啥" tabindex="-1">文章講了啥 <a class="header-anchor" href="#文章講了啥" aria-label="Permalink to “文章講了啥”">​</a></h2><p>Wallen 的核心論點可以拆成幾條：</p><ul><li><strong>Azure 是新搖錢樹，Windows 不是</strong>：微軟已經在雲上贏了，沒必要為 Windows 桌面續命</li><li><strong>微軟應該&quot;登月式飛躍&quot;</strong>：不是&quot;在 Linux 內核上跑 Windows 界面&quot;，而是直接發佈完整的 Microsoft Linux 發行版</li><li><strong>OEM 全切換</strong>：大賣場 PC 出廠直接裝 Microsoft Linux，沒有&quot;半途而廢的餘地&quot;</li><li><strong>保留 Windows Defender</strong>：用户需要防釣魚/惡意 URL，Defender 應該原生集成到 Linux 版</li><li><strong>保留 Microsoft 365</strong>：通過 SaaS 提供，用户感受不到 Windows 沒了</li><li><strong>桌面環境二選一或定製</strong>：GNOME/KDE/Pantheon/Xfce 任選，UI 可以做成&quot;看起來像 Windows&quot;</li></ul><p>核心收益：用户得到更穩定更安全的桌面、IT 不用天天修 Windows 漏洞、Linux 社區終於主導桌面。</p><h2 id="這些觀點今天還成立嗎" tabindex="-1">這些觀點今天還成立嗎？ <a class="header-anchor" href="#這些觀點今天還成立嗎" aria-label="Permalink to “這些觀點今天還成立嗎？”">​</a></h2><div class="table-wrap"><table><thead><tr><th>當時的判斷</th><th>現在 (2026)</th><th>評分</th></tr></thead><tbody><tr><td>微軟會發完整 Linux 桌面發行版</td><td>沒發生，微軟選了&quot;嵌入 Linux 到 Windows&quot;路線</td><td>❌</td></tr><tr><td>Azure 才是微軟的未來</td><td>Azure 現在是雲市場第二，Office 365 + Azure 主導營收</td><td>✅</td></tr><tr><td>OEM 出廠裝 Linux 能主導桌面</td><td>Steam Deck 證明了 Linux 桌面可行，但 OEM 沒跟</td><td>⚠️</td></tr><tr><td>Windows Defender 應該上 Linux</td><td>Microsoft Defender for Linux 已存在，但定位不同</td><td>⚠️</td></tr><tr><td>用户能接受&quot;看起來像 Windows 的 Linux&quot;</td><td>WSL + Windows 11 實現了類似體驗</td><td>⚠️</td></tr></tbody></table></div><h2 id="現在-2026-再讀這篇文章" tabindex="-1">現在 (2026) 再讀這篇文章 <a class="header-anchor" href="#現在-2026-再讀這篇文章" aria-label="Permalink to “現在 (2026) 再讀這篇文章”">​</a></h2><p>Wallen 錯在他假設微軟會做&quot;激進的戰略轉向&quot;，但微軟選了更聰明的漸進路線——把 Linux 嵌入 Windows（WSL）、把 Windows 服務搬到 Linux（SQL Server、Edge、Defender）、把 Linux 體驗帶給所有人（VS Code、GitHub Codespaces）。</p><p>OEM 沒出廠預裝 Microsoft Linux，但<strong>Microsoft Surface 現在默認帶 WSL，Windows 11 也能跑 Linux GUI 應用</strong>。從用户體驗角度，&quot;我既能跑 Windows 軟件又能用 Linux 工具&quot;這個目標已經達成，只是實現路徑不同。</p><p>更重要的是，Wallen 當年沒看到的變量：<strong>AI Agent 時代到來</strong>。2026 年的開發者並不在意「用 Windows 還是 Linux」，他們在乎「AI Agent 能不能跑在本地」。微軟押對的是 GitHub Copilot + VS Code + Azure AI 這條路，不是操作系統本身。</p><p>Wallen 2020 年提出「Microsoft Linux」——路徑沒押對，但 Azure + WSL + VS Code 這套「嵌入 Linux」路線微軟走得更好。</p><hr><p><strong>出處</strong></p>',16)),o("div",L,[o("table",null,[t[10]||(t[10]=o("thead",null,[o("tr",null,[o("th",null,"字段"),o("th",null,"值")])],-1)),o("tbody",null,[o("tr",null,[t[4]||(t[4]=o("td",null,"原文（ARR 風險）",-1)),o("td",null,[i(e,{href:"https://www.zdnet.com/article/linux-based-windows-makes-perfect-sense/",rel:"nofollow noopener"},{default:r(()=>[...t[3]||(t[3]=[n("zdnet.com",-1)])]),_:1})])]),o("tr",null,[t[6]||(t[6]=o("td",null,"LCTT 譯稿源檔",-1)),o("td",null,[i(e,{href:"https://github.com/LCTT/TranslateProject/blob/master/sources/tech/"},{default:r(()=>[...t[5]||(t[5]=[n("github.com/LCTT/TranslateProject",-1)])]),_:1})])]),o("tr",null,[t[8]||(t[8]=o("td",null,"原譯",-1)),o("td",null,[i(e,{href:"https://linux.cn/article-12718-1.html"},{default:r(()=>[...t[7]||(t[7]=[n("linux.cn/article-12718-1.html",-1)])]),_:1})])]),t[9]||(t[9]=o("tr",null,[o("td",null,"發佈"),o("td",null,"2020-10-12")],-1))])])]),t[13]||(t[13]=o("hr",null,null,-1))])}const h=l(f,[["render",p]]);export{C as __pageData,h as default};
